    input logic [63:0] instr_retired,
    input logic [31:0] instruction,
    input logic [0:0] load_use_hazard,
    input logic [31:0] mem_alu_result,
    input logic [31:0] mem_instruction,
    input logic [31:0] mem_rs1_data,
    input logic [31:0] mem_rs2_data,
    input logic [31:0] next_pc,
    input logic [6:0] opcode,
    input logic [31:0] pc,
    input logic [4:0] rd_addr,
    input logic [4:0] rs1_addr,
    input logic [31:0] rs1_data,
    input logic [4:0] rs2_addr,
    input logic [31:0] rs2_data,
    input logic [1:0] ru_data_wr_src,
    input logic [0:0] ru_wr,
    input logic [0:0] stall,
    input logic [0:0] trap_flush,
    input logic [31:0] wb_instruction,
    input logic [4:0] wb_rd_addr,
    input logic [31:0] wb_rd_data,
    input logic [1023:0] reg_values,

    // Video memory port (write-only, processor clock domain)
    output logic        vmem_wr_en,
    output logic [12:0] vmem_wr_addr,
    output logic [15:0] vmem_wr_data
);

    // Field address map (from fields.json)
    localparam logic [12:0] ADDR_CYCLES_AT_DONE = 13'd218;
    localparam logic [12:0] ADDR_INSTR_AT_DONE = 13'd377;
    localparam logic [12:0] ADDR_RU_DATA_WR_SRC = 13'd1198;
    localparam logic [12:0] ADDR_PC = 13'd1292;
    localparam logic [12:0] ADDR_RS1_ADDR = 13'd1316;
    localparam logic [12:0] ADDR_RS2_ADDR = 13'd1324;
    localparam logic [12:0] ADDR_RD_ADDR = 13'd1331;
    localparam logic [12:0] ADDR_INSTRUCTION = 13'd1452;
    localparam logic [12:0] ADDR_NEXT_PC = 13'd1612;
    localparam logic [12:0] ADDR_DATA_WR = 13'd1639;
