    localparam logic [12:0] ADDR_IF_PC = 13'd1772;
    localparam logic [12:0] ADDR_IF_INSTRUCTION = 13'd1932;
    localparam logic [12:0] ADDR_BRANCH = 13'd2092;
    localparam logic [12:0] ADDR_RS1_DATA = 13'd2120;
    localparam logic [12:0] ADDR_RS2_DATA = 13'd2280;
    localparam logic [12:0] ADDR_MEM_ALU_RESULT = 13'd2314;
