    localparam logic [12:0] ADDR_EX_IMM = 13'd5166;
    localparam logic [12:0] ADDR_BRANCH_FLUSH = 13'd5297;
    localparam logic [12:0] ADDR_TRAP_FLUSH = 13'd5457;
