    localparam logic [12:0] ADDR_ALU_A = 13'd6280;
    localparam logic [12:0] ADDR_MEM_RS1_DATA = 13'd6315;
    localparam logic [12:0] ADDR_ALU_B = 13'd6440;
    localparam logic [12:0] ADDR_MEM_RS2_DATA = 13'd6475;
    localparam logic [12:0] ADDR_ALU_RES = 13'd6600;
