    localparam logic [12:0] ADDR_MEM_INSTRUCTION = 13'd6795;
    localparam logic [12:0] ADDR_ALUA_SRC = 13'd6921;
    localparam logic [12:0] ADDR_ALUB_SRC = 13'd6932;
    localparam logic [12:0] ADDR_EX_BRANCH_TAKEN = 13'd6955;
    localparam logic [12:0] ADDR_INSTR_RETIRED = 13'd7152;
    localparam logic [12:0] ADDR_X0 = 13'd1532;
    localparam logic [12:0] ADDR_X1 = 13'd1692;
    localparam logic [12:0] ADDR_X2 = 13'd1852;
    localparam logic [12:0] ADDR_X3 = 13'd2012;
    localparam logic [12:0] ADDR_X4 = 13'd2172;
    localparam logic [12:0] ADDR_X5 = 13'd2332;
    localparam logic [12:0] ADDR_X6 = 13'd2492;
    localparam logic [12:0] ADDR_X7 = 13'd2652;
    localparam logic [12:0] ADDR_X8 = 13'd2812;
    localparam logic [12:0] ADDR_X9 = 13'd2972;
    localparam logic [12:0] ADDR_X10 = 13'd3132;
    localparam logic [12:0] ADDR_X11 = 13'd3292;
    localparam logic [12:0] ADDR_X12 = 13'd3452;
    localparam logic [12:0] ADDR_X13 = 13'd3612;
    localparam logic [12:0] ADDR_X14 = 13'd3772;
    localparam logic [12:0] ADDR_X15 = 13'd3932;
    localparam logic [12:0] ADDR_X16 = 13'd4092;
    localparam logic [12:0] ADDR_X17 = 13'd4252;
    localparam logic [12:0] ADDR_X18 = 13'd4412;
    localparam logic [12:0] ADDR_X19 = 13'd4572;
    localparam logic [12:0] ADDR_X20 = 13'd4732;
    localparam logic [12:0] ADDR_X21 = 13'd4892;
    localparam logic [12:0] ADDR_X22 = 13'd5052;
    localparam logic [12:0] ADDR_X23 = 13'd5212;
    localparam logic [12:0] ADDR_X24 = 13'd5372;
    localparam logic [12:0] ADDR_X25 = 13'd5532;
    localparam logic [12:0] ADDR_X26 = 13'd5692;
    localparam logic [12:0] ADDR_X27 = 13'd5852;
    localparam logic [12:0] ADDR_X28 = 13'd6012;
    localparam logic [12:0] ADDR_X29 = 13'd6172;
    localparam logic [12:0] ADDR_X30 = 13'd6332;
    localparam logic [12:0] ADDR_X31 = 13'd6492;

    // The groups rotate: one group is written per cycle.
    localparam int GRP_PROC = 0;
    localparam int GRP_PROC1 = 1;
    localparam int GRP_PROC2 = 2;
    localparam int GRP_REGS = 3;

    localparam int N_GROUPS = 4;
    localparam int GRP_W    = 2;
    localparam int N_CHARS  = 573;

    localparam int N_PROC = 121;
    localparam int CTR_PROC_W = 7;
    logic [CTR_PROC_W-1:0] ctr_proc;
    localparam int N_PROC1 = 125;
    localparam int CTR_PROC1_W = 7;
    logic [CTR_PROC1_W-1:0] ctr_proc1;
    localparam int N_PROC2 = 71;
    localparam int CTR_PROC2_W = 7;
    logic [CTR_PROC2_W-1:0] ctr_proc2;
    localparam int N_REGS = 256;
    localparam int CTR_REGS_W = 8;
    logic [CTR_REGS_W-1:0] ctr_regs;

    logic [GRP_W-1:0] grp_ctr;

    // Register table, stage 1: the row of the character being written.
    localparam logic [415:0] REG_ADDR = {13'd6492, 13'd6332, 13'd6172, 13'd6012, 13'd5852, 13'd5692, 13'd5532, 13'd5372, 13'd5212, 13'd5052, 13'd4892, 13'd4732, 13'd4572, 13'd4412, 13'd4252, 13'd4092, 13'd3932, 13'd3772, 13'd3612, 13'd3452, 13'd3292, 13'd3132, 13'd2972, 13'd2812, 13'd2652, 13'd2492, 13'd2332, 13'd2172, 13'd2012, 13'd1852, 13'd1692, 13'd1532};
    logic [31:0] reg_value;
    logic [12:0] reg_addr;
    logic [2:0]  reg_col;

    // Snapshot bank - the whole screen is rendered from one instant
    logic [31:0] snap_alu_a;
    logic [31:0] snap_alu_b;
    logic [4:0] snap_alu_op;
    logic [31:0] snap_alu_res;
    logic [1:0] snap_alua_src;
    logic [0:0] snap_alub_src;
    logic [4:0] snap_br_op;
    logic [0:0] snap_branch;
    logic [0:0] snap_branch_flush;
    logic [63:0] snap_cycles_at_done;
    logic [31:0] snap_data_wr;
    logic [31:0] snap_dm_addr;
    logic [2:0] snap_dm_ctrl;
    logic [31:0] snap_dm_rdata;
    logic [31:0] snap_dm_wdata;
    logic [0:0] snap_dm_wr;
    logic [31:0] snap_ex_alu_result;
    logic [0:0] snap_ex_branch_taken;
    logic [31:0] snap_ex_imm;
    logic [31:0] snap_ex_instruction;
    logic [31:0] snap_ex_pc;
    logic [31:0] snap_ex_rs1_data;
    logic [31:0] snap_ex_rs2_data;
    logic [0:0] snap_flush;
    logic [2:0] snap_funct3;
    logic [6:0] snap_funct7;
    logic [31:0] snap_id_instruction;
    logic [31:0] snap_id_pc;
    logic [31:0] snap_if_instruction;
    logic [31:0] snap_if_pc;
    logic [31:0] snap_imm_out;
    logic [2:0] snap_imm_src;
    logic [63:0] snap_instr_at_done;
    logic [63:0] snap_instr_retired;
    logic [31:0] snap_instruction;
    logic [0:0] snap_load_use_hazard;
    logic [31:0] snap_mem_alu_result;
    logic [31:0] snap_mem_instruction;
    logic [31:0] snap_mem_rs1_data;
    logic [31:0] snap_mem_rs2_data;
    logic [31:0] snap_next_pc;
    logic [6:0] snap_opcode;
    logic [31:0] snap_pc;
    logic [4:0] snap_rd_addr;
    logic [4:0] snap_rs1_addr;
    logic [31:0] snap_rs1_data;
    logic [4:0] snap_rs2_addr;
    logic [31:0] snap_rs2_data;
    logic [1:0] snap_ru_data_wr_src;
    logic [0:0] snap_ru_wr;
    logic [0:0] snap_stall;
    logic [0:0] snap_trap_flush;
    logic [31:0] snap_wb_instruction;
    logic [4:0] snap_wb_rd_addr;
    logic [31:0] snap_wb_rd_data;
    logic [1023:0] snap_reg_values;

    // Derived signals used by the attribute expressions.
    wire stage_if_active  = (snap_if_instruction != 32'h00000000) &&
                             (snap_if_instruction != 32'h00000013);
    wire stage_id_active  = (snap_id_instruction != 32'h00000000) &&
                             (snap_id_instruction != 32'h00000013);
    wire stage_ex_active  = (snap_ex_instruction != 32'h00000000) &&
                             (snap_ex_instruction != 32'h00000013);
    wire stage_mem_active = (snap_mem_instruction != 32'h00000000) &&
                             (snap_mem_instruction != 32'h00000013);
    wire stage_wb_active  = (snap_wb_instruction != 32'h00000000) &&
                             (snap_wb_instruction != 32'h00000013);
    wire mem_access       = (snap_mem_instruction[6:0] == 7'b0000011) ||
                             (snap_mem_instruction[6:0] == 7'b0100011);
    wire mem_write_access = snap_dm_wr;
    wire mem_read_access  = mem_access && !mem_write_access;

    // Helper functions: value --> ASCII
    function automatic [7:0] hex_digit (
        input logic [63:0] value,
        input int          nibble
    );
        logic [63:0] shifted;
        logic [3:0]  d;
        shifted = value >> (nibble * 4);
        d = shifted[3:0];
        hex_digit = (d < 4'd10) ? (8'd48 + d) : (8'd55 + d);  // '0'-'9', 'A'-'F'
    endfunction

    function automatic [7:0] bin_digit (
        input logic [63:0] value,
        input int          bit_idx
    );
        logic [63:0] shifted;
        shifted = value >> bit_idx;
        bin_digit = 8'd48 + shifted[0];  // '0' or '1'
    endfunction

    // Round-robin FSM - one char per cycle, groups alternate
    logic        wr_en;
    logic [12:0] wr_addr;
    logic [7:0]  wr_data;
    logic [7:0]  wr_attr;

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            grp_ctr <= '0;
            reg_value <= '0;
            reg_addr  <= '0;
            reg_col   <= '0;
            snap_alu_a <= '0;
            snap_alu_b <= '0;
            snap_alu_op <= '0;
            snap_alu_res <= '0;
            snap_alua_src <= '0;
            snap_alub_src <= '0;
            snap_br_op <= '0;
            snap_branch <= '0;
            snap_branch_flush <= '0;
            snap_cycles_at_done <= '0;
            snap_data_wr <= '0;
            snap_dm_addr <= '0;
            snap_dm_ctrl <= '0;
            snap_dm_rdata <= '0;
            snap_dm_wdata <= '0;
            snap_dm_wr <= '0;
            snap_ex_alu_result <= '0;
            snap_ex_branch_taken <= '0;
            snap_ex_imm <= '0;
            snap_ex_instruction <= '0;
            snap_ex_pc <= '0;
            snap_ex_rs1_data <= '0;
            snap_ex_rs2_data <= '0;
            snap_flush <= '0;
            snap_funct3 <= '0;
            snap_funct7 <= '0;
            snap_id_instruction <= '0;
            snap_id_pc <= '0;
            snap_if_instruction <= '0;
            snap_if_pc <= '0;
            snap_imm_out <= '0;
            snap_imm_src <= '0;
            snap_instr_at_done <= '0;
            snap_instr_retired <= '0;
            snap_instruction <= '0;
            snap_load_use_hazard <= '0;
            snap_mem_alu_result <= '0;
            snap_mem_instruction <= '0;
            snap_mem_rs1_data <= '0;
            snap_mem_rs2_data <= '0;
            snap_next_pc <= '0;
            snap_opcode <= '0;
            snap_pc <= '0;
            snap_rd_addr <= '0;
            snap_rs1_addr <= '0;
            snap_rs1_data <= '0;
            snap_rs2_addr <= '0;
            snap_rs2_data <= '0;
            snap_ru_data_wr_src <= '0;
            snap_ru_wr <= '0;
            snap_stall <= '0;
            snap_trap_flush <= '0;
            snap_wb_instruction <= '0;
            snap_wb_rd_addr <= '0;
            snap_wb_rd_data <= '0;
            snap_reg_values <= '0;
            ctr_proc <= '0;
            ctr_proc1 <= '0;
            ctr_proc2 <= '0;
            ctr_regs <= '0;
        end else begin
            grp_ctr <= (grp_ctr == N_GROUPS - 1) ? '0 : grp_ctr + 1'b1;
            case (grp_ctr)
                GRP_PROC: begin
                    ctr_proc <= (ctr_proc == N_PROC - 1) ? '0 : ctr_proc + 1'b1;
                    // Load the bank at the end of a sweep, so the next sweep
                    // renders every character from the same captured instant.
                    if (ctr_proc == N_PROC - 1) begin
                    snap_cycles_at_done <= cycles_at_done;
                    snap_instr_at_done <= instr_at_done;
                    snap_ru_data_wr_src <= ru_data_wr_src;
                    snap_pc <= pc;
                    snap_rs1_addr <= rs1_addr;
                    snap_rs2_addr <= rs2_addr;
                    snap_rd_addr <= rd_addr;
                    snap_instruction <= instruction;
                    snap_next_pc <= next_pc;
                    snap_data_wr <= data_wr;
                    snap_ru_wr <= ru_wr;
                    snap_if_pc <= if_pc;
                    snap_if_instruction <= if_instruction;
                    snap_branch <= branch;
                    snap_rs1_data <= rs1_data;
                    snap_rs2_data <= rs2_data;
                    snap_mem_alu_result <= mem_alu_result;
                    snap_wb_instruction <= wb_instruction;
                    end
                end
                GRP_PROC1: begin
                    ctr_proc1 <= (ctr_proc1 == N_PROC1 - 1) ? '0 : ctr_proc1 + 1'b1;
                    // Load the bank at the end of a sweep, so the next sweep
                    // renders every character from the same captured instant.
                    if (ctr_proc1 == N_PROC1 - 1) begin
                    snap_imm_out <= imm_out;
                    snap_imm_src <= imm_src;
                    snap_wb_rd_addr <= wb_rd_addr;
                    snap_wb_rd_data <= wb_rd_data;
                    snap_opcode <= opcode;
                    snap_funct3 <= funct3;
                    snap_funct7 <= funct7;
                    snap_id_pc <= id_pc;
                    snap_id_instruction <= id_instruction;
                    snap_dm_addr <= dm_addr;
                    snap_ex_pc <= ex_pc;
                    snap_dm_wdata <= dm_wdata;
                    snap_ex_instruction <= ex_instruction;
                    snap_dm_rdata <= dm_rdata;
                    snap_ex_rs1_data <= ex_rs1_data;
                    snap_dm_ctrl <= dm_ctrl;
                    snap_stall <= stall;
                    snap_ex_rs2_data <= ex_rs2_data;
                    snap_dm_wr <= dm_wr;
                    snap_load_use_hazard <= load_use_hazard;
                    snap_ex_imm <= ex_imm;
                    snap_branch_flush <= branch_flush;
                    snap_trap_flush <= trap_flush;
                    snap_flush <= flush;
                    snap_alu_a <= alu_a;
                    end
                end
                GRP_PROC2: begin
                    ctr_proc2 <= (ctr_proc2 == N_PROC2 - 1) ? '0 : ctr_proc2 + 1'b1;
                    // Load the bank at the end of a sweep, so the next sweep
                    // renders every character from the same captured instant.
                    if (ctr_proc2 == N_PROC2 - 1) begin
                    snap_mem_rs1_data <= mem_rs1_data;
                    snap_alu_b <= alu_b;
                    snap_mem_rs2_data <= mem_rs2_data;
                    snap_alu_res <= alu_res;
                    snap_ex_alu_result <= ex_alu_result;
                    snap_alu_op <= alu_op;
                    snap_br_op <= br_op;
                    snap_mem_instruction <= mem_instruction;
                    snap_alua_src <= alua_src;
                    snap_alub_src <= alub_src;
                    snap_ex_branch_taken <= ex_branch_taken;
                    snap_instr_retired <= instr_retired;
                    end
                end
                GRP_REGS: begin
                    ctr_regs <= (ctr_regs == N_REGS - 1) ? '0 : ctr_regs + 1'b1;
                    // Load the bank at the end of a sweep, so the next sweep
                    // renders every character from the same captured instant.
                    if (ctr_regs == N_REGS - 1) begin
                    snap_reg_values <= reg_values;
                    end
                    // Stage 1: select the register row of this character.
                    reg_value <= snap_reg_values[32*ctr_regs[7:3] +: 32];
                    reg_addr  <= REG_ADDR[13*ctr_regs[7:3] +: 13];
                    reg_col   <= ctr_regs[2:0];
                end
                default: ;  // no write
            endcase
        end
    end

    always_comb begin
        // Default: no write
        wr_en   = 1'b0;
        wr_addr = '0;
        wr_data = 8'h20;  // space
        wr_attr = 8'h09;  // body colour

        case (grp_ctr)
            GRP_PROC: begin
                unique case (ctr_proc)
            0: begin wr_en = 1'b1; wr_addr = ADDR_CYCLES_AT_DONE + 13'd0; wr_data = hex_digit(snap_cycles_at_done, 15); wr_attr = 8'h09; end
            1: begin wr_en = 1'b1; wr_addr = ADDR_CYCLES_AT_DONE + 13'd1; wr_data = hex_digit(snap_cycles_at_done, 14); wr_attr = 8'h09; end
            2: begin wr_en = 1'b1; wr_addr = ADDR_CYCLES_AT_DONE + 13'd2; wr_data = hex_digit(snap_cycles_at_done, 13); wr_attr = 8'h09; end
            3: begin wr_en = 1'b1; wr_addr = ADDR_CYCLES_AT_DONE + 13'd3; wr_data = hex_digit(snap_cycles_at_done, 12); wr_attr = 8'h09; end
            4: begin wr_en = 1'b1; wr_addr = ADDR_CYCLES_AT_DONE + 13'd4; wr_data = hex_digit(snap_cycles_at_done, 11); wr_attr = 8'h09; end
            5: begin wr_en = 1'b1; wr_addr = ADDR_CYCLES_AT_DONE + 13'd5; wr_data = hex_digit(snap_cycles_at_done, 10); wr_attr = 8'h09; end
            6: begin wr_en = 1'b1; wr_addr = ADDR_CYCLES_AT_DONE + 13'd6; wr_data = hex_digit(snap_cycles_at_done, 9); wr_attr = 8'h09; end
            7: begin wr_en = 1'b1; wr_addr = ADDR_CYCLES_AT_DONE + 13'd7; wr_data = hex_digit(snap_cycles_at_done, 8); wr_attr = 8'h09; end
            8: begin wr_en = 1'b1; wr_addr = ADDR_CYCLES_AT_DONE + 13'd8; wr_data = hex_digit(snap_cycles_at_done, 7); wr_attr = 8'h09; end
            9: begin wr_en = 1'b1; wr_addr = ADDR_CYCLES_AT_DONE + 13'd9; wr_data = hex_digit(snap_cycles_at_done, 6); wr_attr = 8'h09; end
